import { marked, type Token, type Tokens } from 'marked';

const SAFE_LINK_PROTOCOLS = new Set(['http:', 'https:', 'mailto:']);

/** A link to the web, an inbox, or within the app (relative URLs resolve to this origin). */
function isSafeHref(href: string): boolean {
    try {
        return SAFE_LINK_PROTOCOLS.has(new URL(href, window.location.href).protocol);
    } catch {
        return false;
    }
}

function isSameOriginImage(src: string): boolean {
    try {
        const url = new URL(src, window.location.href);
        return (url.protocol === 'http:' || url.protocol === 'https:') && url.origin === window.location.origin;
    } catch {
        return false;
    }
}

/**
 * Render a markdown string to a DocumentFragment using `marked.lexer()` to get tokens, then
 * walking those tokens into DOM nodes with `document.createElement` / `appendChild`. **No HTML
 * string ever touches `innerHTML`** — this is the only sanctioned markdown renderer in the PWA
 * for user-controlled content (story bodies, scrumboard notes).
 *
 * Unknown token types fall back to a text node containing the raw markdown source — fail-loud,
 * so a future marked version that emits a new token shape doesn't silently disappear from the
 * rendered output. Tests assert no token type from a small representative corpus is dropped.
 */
export function renderMarkdown(source: string, options: RenderOptions = {}): DocumentFragment {
    const tokens = marked.lexer(source);
    const fragment = document.createDocumentFragment();
    appendTokens(fragment, tokens, options);
    return fragment;
}

export interface RenderOptions {
    /** Base heading level for any `#` heading in the source. Defaults to 3 (`h3`). */
    baseHeadingLevel?: 1 | 2 | 3 | 4 | 5;
    /** Called once for any unknown token type the walker doesn't recognize. */
    onUnknownToken?: (token: Token) => void;
}

type AnyToken = Token & { raw?: string; tokens?: Token[]; text?: string };

function appendTokens(parent: Node, tokens: readonly Token[], options: RenderOptions): void {
    for (const token of tokens) appendToken(parent, token as AnyToken, options);
}

function appendToken(parent: Node, token: AnyToken, options: RenderOptions): void {
    switch (token.type) {
        case 'space':
            return;
        case 'heading': {
            const t = token as Tokens.Heading;
            const base = options.baseHeadingLevel ?? 3;
            const level = Math.min(6, base + (t.depth - 1));
            const el = document.createElement(`h${level}`);
            appendInlineTokens(el, t.tokens ?? [], options);
            parent.appendChild(el);
            return;
        }
        case 'paragraph': {
            const t = token as Tokens.Paragraph;
            const el = document.createElement('p');
            appendInlineTokens(el, t.tokens ?? [], options);
            parent.appendChild(el);
            return;
        }
        case 'list': {
            const t = token as Tokens.List;
            const el = document.createElement(t.ordered ? 'ol' : 'ul');
            if (t.ordered && typeof t.start === 'number' && t.start !== 1) {
                el.setAttribute('start', String(t.start));
            }
            for (const item of t.items) appendListItem(el, item, options);
            parent.appendChild(el);
            return;
        }
        case 'code': {
            const t = token as Tokens.Code;
            const pre = document.createElement('pre');
            const code = document.createElement('code');
            if (t.lang) code.setAttribute('data-lang', t.lang);
            code.textContent = t.text;
            pre.appendChild(code);
            parent.appendChild(pre);
            return;
        }
        case 'blockquote': {
            const t = token as Tokens.Blockquote;
            const el = document.createElement('blockquote');
            appendTokens(el, t.tokens ?? [], options);
            parent.appendChild(el);
            return;
        }
        case 'table':
            appendTable(parent, token as Tokens.Table, options);
            return;
        case 'hr':
            parent.appendChild(document.createElement('hr'));
            return;
        case 'html': {
            // We refuse to render raw HTML from user-controlled markdown. Emit the source text so
            // the user can see what they wrote — it just won't be interpreted as markup.
            const t = token as Tokens.HTML;
            parent.appendChild(document.createTextNode(t.raw ?? ''));
            return;
        }
        default:
            appendInlineToken(parent, token, options);
    }
}

function appendListItem(parent: HTMLElement, item: Tokens.ListItem, options: RenderOptions): void {
    const li = document.createElement('li');
    if (item.task) {
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.disabled = true;
        if (item.checked) checkbox.checked = true;
        li.appendChild(checkbox);
        li.appendChild(document.createTextNode(' '));
    }
    if (item.loose) {
        appendTokens(li, item.tokens ?? [], options);
    } else {
        // For tight lists marked still emits text inside paragraph tokens; render the inner
        // tokens directly without wrapping each in <p>.
        for (const child of item.tokens ?? []) {
            if ((child as AnyToken).type === 'text') {
                appendInlineTokens(li, (child as Tokens.Text).tokens ?? [{ type: 'text', raw: (child as Tokens.Text).text, text: (child as Tokens.Text).text } as unknown as Token], options);
            } else {
                appendToken(li, child as AnyToken, options);
            }
        }
    }
    parent.appendChild(li);
}

function appendTable(parent: Node, token: Tokens.Table, options: RenderOptions): void {
    const table = document.createElement('table');
    const thead = document.createElement('thead');
    const headRow = document.createElement('tr');
    for (let i = 0; i < token.header.length; i++) {
        const cell = token.header[i];
        const th = document.createElement('th');
        const align = token.align[i];
        if (align) th.style.textAlign = align;
        appendInlineTokens(th, cell.tokens ?? [], options);
        headRow.appendChild(th);
    }
    thead.appendChild(headRow);
    table.appendChild(thead);
    const tbody = document.createElement('tbody');
    for (const row of token.rows) {
        const tr = document.createElement('tr');
        for (let i = 0; i < row.length; i++) {
            const cell = row[i];
            const td = document.createElement('td');
            const align = token.align[i];
            if (align) td.style.textAlign = align;
            appendInlineTokens(td, cell.tokens ?? [], options);
            tr.appendChild(td);
        }
        tbody.appendChild(tr);
    }
    table.appendChild(tbody);
    parent.appendChild(table);
}

function appendInlineTokens(parent: Node, tokens: readonly Token[], options: RenderOptions): void {
    for (const token of tokens) appendInlineToken(parent, token as AnyToken, options);
}

function appendInlineToken(parent: Node, token: AnyToken, options: RenderOptions): void {
    switch (token.type) {
        case 'text': {
            const t = token as Tokens.Text;
            if (t.tokens && t.tokens.length > 0) {
                appendInlineTokens(parent, t.tokens, options);
            } else {
                parent.appendChild(document.createTextNode(t.text ?? t.raw ?? ''));
            }
            return;
        }
        case 'strong': {
            const t = token as Tokens.Strong;
            const el = document.createElement('strong');
            appendInlineTokens(el, t.tokens ?? [], options);
            parent.appendChild(el);
            return;
        }
        case 'em': {
            const t = token as Tokens.Em;
            const el = document.createElement('em');
            appendInlineTokens(el, t.tokens ?? [], options);
            parent.appendChild(el);
            return;
        }
        case 'codespan': {
            const t = token as Tokens.Codespan;
            const el = document.createElement('code');
            el.textContent = t.text;
            parent.appendChild(el);
            return;
        }
        case 'del': {
            const t = token as Tokens.Del;
            const el = document.createElement('del');
            appendInlineTokens(el, t.tokens ?? [], options);
            parent.appendChild(el);
            return;
        }
        case 'link': {
            const t = token as Tokens.Link;
            // Story 383: a link that would not go to the web, an inbox or within the app keeps
            // only its text — a javascript: href ran when tapped.
            if (!isSafeHref(t.href)) {
                appendInlineTokens(parent, t.tokens ?? [], options);
                return;
            }
            const a = document.createElement('a');
            a.setAttribute('href', t.href);
            if (t.title) a.setAttribute('title', t.title);
            appendInlineTokens(a, t.tokens ?? [], options);
            parent.appendChild(a);
            return;
        }
        case 'image': {
            const t = token as Tokens.Image;
            // Story 383: same-origin images only; anything else shows its alt text.
            if (!isSameOriginImage(t.href)) {
                parent.appendChild(document.createTextNode(t.text ?? ''));
                return;
            }
            const img = document.createElement('img');
            img.setAttribute('src', t.href);
            img.setAttribute('alt', t.text ?? '');
            if (t.title) img.setAttribute('title', t.title);
            parent.appendChild(img);
            return;
        }
        case 'br':
            parent.appendChild(document.createElement('br'));
            return;
        case 'escape': {
            const t = token as Tokens.Escape;
            parent.appendChild(document.createTextNode(t.text));
            return;
        }
        case 'html': {
            const t = token as Tokens.HTML;
            parent.appendChild(document.createTextNode(t.raw ?? ''));
            return;
        }
        default:
            options.onUnknownToken?.(token);
            parent.appendChild(document.createTextNode(token.raw ?? ''));
    }
}
